ed direction.\n47:         direction = w.astype(np.float64).sum(axis=0)\n48:         direction /= np.linalg.norm(direction)\n49:         x /= np.linalg.norm(x)\n50:         x = cfg[\"mix\"] * direction + (1.0 - cfg[\"mix\"]) * x\n51:         wf = w.astype(np.float64)\n52:         scale = np.max(np.abs(wf), axis=1, keepdims=True) / 7.0\n53:         residual = (np.clip(np.floor(wf / scale + 0.5), -7, 7) * scale - wf).sum(axis=0)\n54:         residual /= np.linalg.norm(residual)\n55:         x += cfg[\"residual\"] * residual\n56:         return tensor(x), tensor(w)\n57:     t, d = cfg[\"t\"], cfg[\"d\"]\n58:     a = np.full((t, d), cfg[\"decay\"], dtype=np.float64)\n59:     b = rng.standard_normal((t, d)) * cfg[\"noise\"]\n60:     b += cfg[\"bias\"]\n61:     return tensor(a), tensor(b)",
